['Fraction','a⁄b','\\frac{a}{b}','Essentials'],['Exponent','x²','x^{2}','Essentials'],['Root','√x','\\sqrt{x}','Essentials'],['Subscript','x₁','x_{1}','Essentials'],['Brackets','( )','\\left(x\\right)','Essentials'],
['Mixed number','1⅔','1\\frac{2}{3}','Fractions'],['Add fractions','+','\\frac{1}{2}+\\frac{1}{3}','Fractions'],['Multiply fractions','×','\\frac{2}{3}\\times\\frac{4}{5}','Fractions'],['Equivalent','≡','\\frac{a}{b}=\\frac{ka}{kb}','Fractions'],['Percent','%','25\\%','Fractions'],
['Pi','π','\\pi','Symbols'],['Theta','θ','\\theta','Symbols'],['Alpha','α','\\alpha','Symbols'],['Beta','β','\\beta','Symbols'],['Delta','Δ','\\Delta','Symbols'],['Infinity','∞','\\infty','Symbols'],['Not equal','≠','\\ne','Symbols'],['Approx','≈','\\approx','Symbols'],['Less equal','≤','\\le','Symbols'],['Greater equal','≥','\\ge','Symbols'],['Plus-minus','±','\\pm','Symbols'],['Times','×','\\times','Symbols'],['Divide','÷','\\div','Symbols'],['Set union','∪','\\cup','Symbols'],['In set','∈','\\in','Symbols'],
['Integral','∫','\\int_{a}^{b} f(x)\\,dx','Calculus'],['Derivative','d/dx','\\frac{d}{dx}f(x)','Calculus'],['Partial','∂','\\frac{\\partial f}{\\partial x}','Calculus'],['Limit','lim','\\lim_{x\\to 0} f(x)','Calculus'],['Summation','Σ','\\sum_{i=1}^{n} i','Calculus'],['Product','Π','\\prod_{i=1}^{n} i','Calculus'],
['Vector','v⃗','\\vec{v}','Algebra'],['Absolute value','|x|','\\left|x\\right|','Algebra'],['Logarithm','log','\\log_{2}(x)','Algebra'],['Matrix 2×2','[ ]','\\begin{bmatrix}a&b\\\\c&d\\end{bmatrix}','Algebra'],['Matrix 3×3','3×3','\\begin{bmatrix}1&0&0\\\\0&1&0\\\\0&0&1\\end{bmatrix}','Algebra'],['Cases','{','\\begin{cases}x+2&x>0\\\\-x&x\\le 0\\end{cases}','Algebra'],['Binomial','(n k)','\\binom{n}{k}','Algebra'],
['Angle','∠','\\angle ABC','Geometry'],['Degree','°','90^{\\circ}','Geometry'],['Parallel','∥','a\\parallel b','Geometry'],['Perpendicular','⊥','a\\perp b','Geometry'],['Triangle','△','\\triangle ABC','Geometry'],['Distance','d','d=\\sqrt{(x_2-x_1)^2+(y_2-y_1)^2}','Geometry']
