function showHelp(initial='start'){
 modal('LaTeX Studio Help Centre',`<div class="help-shell"><aside class="help-navigation"><label class="help-search-label" for="helpSearch">Search help topics</label><input id="helpSearch" class="help-search" type="search" placeholder="Search help…" autocomplete="off" aria-label="Search help articles"><div id="helpTopicList" class="help-topic-list" aria-label="Help topics"></div></aside><article class="help-article" id="helpArticle" tabindex="0"></article></div>`,[{label:'Close Help',class:'primary',click:closeModal}],true);
 const list=$('#helpTopicList'),article=$('#helpArticle'),search=$('#helpSearch');let selected=helpTopics.some(t=>t.id===initial)?initial:'start';
 function renderArticle(){const t=helpTopics.find(t=>t.id===selected)||helpTopics[0];article.innerHTML=`<div class="help-breadcrumb">HELP / ${esc(t.section)}</div><h2>${esc(t.title)}</h2><p class="help-article-lead">${esc(t.summary)}</p>${t.body}`;list.querySelectorAll('[data-help-topic]').forEach(b=>b.classList.toggle('active',b.dataset.helpTopic===selected));}
 function renderList(){const term=search.value.trim().toLowerCase();const matching=helpTopics.filter(t=>(t.title+' '+t.summary+' '+t.section+' '+t.body.replace(/<[^>]*>/g,' ')).toLowerCase().includes(term)).sort((a,b)=>!term?0:((b.title.toLowerCase().includes(term)?3:0)+(b.summary.toLowerCase().includes(term)?2:0)+(b.section.toLowerCase().includes(term)?1:0))-((a.title.toLowerCase().includes(term)?3:0)+(a.summary.toLowerCase().includes(term)?2:0)+(a.section.toLowerCase().includes(term)?1:0)));if(!matching.length){list.innerHTML='<div class="help-no-results">No matching topics. Try a shorter search.</div>';article.innerHTML='<h2>No matching results</h2><p>Try searching for “equation”, “PDF”, “template”, or “graph”.</p>';return}if(!matching.some(t=>t.id===selected))selected=matching[0].id;let section='';list.innerHTML=matching.map(t=>{let heading='';if(t.section!==section){section=t.section;heading=`<div class="help-section-label">${esc(section)}</div>`}return heading+`<button data-help-topic="${t.id}" class="help-topic" title="${esc(t.summary)}">${esc(t.title)}</button>`}).join('');renderArticle()}
 list.addEventListener('click',e=>{const b=e.target.closest('[data-help-topic]');if(!b)return;selected=b.dataset.helpTopic;renderArticle();article.scrollTop=0});search.addEventListener('input',renderList);renderList();
}

