function gcd(a,b){while(b)[a,b]=[b,a%b];return Math.abs(a)||1}
function makePracticeQuestion(topic,level){const pick=(a,b)=>a+Math.floor(Math.random()*(b-a+1));const frac=(a,b)=>`\\frac{${a}}{${b}}`;const max=level===1?8:level===2?15:24;
 if(topic==='fractions'){const b=pick(2,max),d=pick(2,max),a=pick(1,b-1),c=pick(1,d-1),op=pick(0,1)?'+':'-';let n=op==='+'?a*d+b*c:a*d-b*c,den=b*d,g=gcd(Math.abs(n),den);return {q:`${frac(a,b)}${op}${frac(c,d)}`,a:`${n<0?'-':''}${frac(Math.abs(n/g),den/g)}`,steps:`${frac(a,b)} ${op} ${frac(c,d)} = ${frac(a*d,b*d)} ${op} ${frac(b*c,b*d)} = ${n<0?'-':''}${frac(Math.abs(n/g),den/g)}`}}
 if(topic==='integers'){const a=pick(-max,max),b=pick(-max,max),ops=['+','-','\\times'],op=ops[pick(0,level===1?1:2)],n=op==='+'?a+b:op==='-'?a-b:a*b;return {q:`(${a})${op}(${b})`,a:String(n),steps:`${op==='\\times'?'Multiply using integer sign rules':'Combine the signed integers'}: ${n}`}}
 if(topic==='exponents'){const base=pick(2,level===3?8:5),a=pick(1,5),b=pick(1,4),which=pick(0,1),exp=which?a+b:a*b;return {q:which?`${base}^{${a}}\\cdot ${base}^{${b}}`:`(${base}^{${a}})^{${b}}`,a:`${base}^{${exp}}`,steps:which?`Same base: add exponents, ${a}+${b}=${exp}`:`Power of a power: multiply exponents, ${a}\\times ${b}=${exp}`}}
 if(topic==='algebra'){const x=pick(-max,max),a=pick(1,max),b=pick(-max,max),total=a*x+b;return {q:`${a}x${b>=0?'+':''}${b}=${total}`,a:`x=${x}`,steps:`${a}x=${total-b}\\quad\\Rightarrow\\quad x=\\frac{${total-b}}{${a}}=${x}`}}
 if(topic==='ratios'){const a=pick(2,max),b=pick(2,max),factor=pick(2,level+3);return {q:`${a}:${b}=x:${b*factor}`,a:`x=${a*factor}`,steps:`Scale by ${factor}: x=${a}\\times${factor}=${a*factor}`}}
 const p=pick(1,9)*10,whole=pick(2,max*5),value=p*whole/100;return {q:`${p}\\%\\;\\text{of}\\;${whole}`,a:numberString(value),steps:`${frac(p,100)}\\times${whole}=${numberString(value)}`};
}
