function safeMathSvg(tex,display=false){try{const mj=MathJax.tex2svg(String(tex||''),{display}),svg=mj.querySelector('svg');if(svg){svg.setAttribute('aria-label',String(tex||''));return svg.outerHTML}}catch(e){console.warn('Math typesetting:',e)}return `<code>${esc(String(tex||''))}</code>`}
