function limitNumberInput(el,commit=false){if(!el||!el.matches('input[type=number]'))return;const value=Number(el.value),min=el.min===''?-Infinity:Number(el.min),max=el.max===''?Infinity:Number(el.max);if(el.value===''||!Number.isFinite(value)){if(commit&&Number.isFinite(min))el.value=String(min);return}if(value>max){if(['wsCount','tvCount'].includes(el.id))notify(`Maximum for this selection: ${max} unique questions${el.id==='tvCount'?' per version':''}.`,'error');el.value=String(max)}else if(commit&&value<min)el.value=String(min);if(commit&&el.step&&el.step!=='any'&&Number.isFinite(Number(el.step))&&Number(el.step)>=1)el.value=String(Math.round(Number(el.value)))}
