/* Editor-owned rich clipboard and moveable math/diagram blocks. */
let activePortableBlock=null, internalClipboard=null, movingBlock=null, lastDropAnchor=null;
function cleanPortableMarkup(html){
 const root=document.createElement('div');root.innerHTML=sanitizeHTML(html);
 root.querySelectorAll('mjx-container,mjx-assistive-mml,.math-render-error,[data-drag-hint]').forEach(n=>n.remove());
 root.querySelectorAll('.math-chip,.math-block,.graph-block').forEach(n=>{n.innerHTML='';n.removeAttribute('data-selected');n.removeAttribute('draggable');n.removeAttribute('tabindex');n.contentEditable='false'});
 return root.innerHTML;
}
function selectedContentForClipboard(){
 const selection=window.getSelection();
 if(selection?.rangeCount&&!selection.isCollapsed&&editor.contains(selection.anchorNode)&&editor.contains(selection.focusNode)){
  const wrap=document.createElement('div');wrap.append(selection.getRangeAt(0).cloneContents());
  const html=cleanPortableMarkup(wrap.innerHTML);return {html,plain:selection.toString(),range:selection.getRangeAt(0)};
 }
 if(activePortableBlock&&editor.contains(activePortableBlock))return {html:cleanPortableMarkup(activePortableBlock.outerHTML),plain:activePortableBlock.dataset.latex||activePortableBlock.dataset.caption||activePortableBlock.textContent||'',node:activePortableBlock};
 return null;
}
function copyEventFromEditor(e,cut=false){
 const item=selectedContentForClipboard();if(!item)return;
 internalClipboard={html:item.html,plain:item.plain};
 if(e.clipboardData){e.clipboardData.setData('text/html',item.html);e.clipboardData.setData('text/plain',item.plain);e.preventDefault()}
 if(cut){if(item.node){item.node.remove();activePortableBlock=null}else item.range?.deleteContents();updateAll();notify('Selection cut; use Ctrl+V to paste it.')}
 else notify('Copied with editable formatting.');
}
function insertPortableHtml(html){
 restoreSelection();const markup=cleanPortableMarkup(html);if(!markup)return;
 document.execCommand('insertHTML',false,markup);
 renderAll();updateAll();
}
function pasteEventInEditor(e){
 if(!editor.contains(e.target))return;
 const html=e.clipboardData?.getData('text/html'),text=e.clipboardData?.getData('text/plain');
 if(!html&&!text)return;
 e.preventDefault();
 if(html)insertPortableHtml(html);
 else{restoreSelection();document.execCommand('insertText',false,text);updateAll()}
 activePortableBlock=null;
}
async function pasteFromToolbar(){
 try{
  if(navigator.clipboard?.read){const clips=await navigator.clipboard.read();for(const item of clips){if(item.types.includes('text/html')){const blob=await item.getType('text/html');insertPortableHtml(await blob.text());return}if(item.types.includes('text/plain')){const blob=await item.getType('text/plain');restoreSelection();document.execCommand('insertText',false,await blob.text());updateAll();return}}}
  if(navigator.clipboard?.readText){const text=await navigator.clipboard.readText();restoreSelection();document.execCommand('insertText',false,text);updateAll();return}
 }catch(e){console.warn('System clipboard unavailable, using local copy buffer.',e)}
 if(internalClipboard){insertPortableHtml(internalClipboard.html||esc(internalClipboard.plain));notify('Pasted editable content.')}else notify('Click in the document and use Ctrl+V (or ⌘+V) to paste.');
}
function copyFromToolbar(){
 if(!selectedContentForClipboard()){notify('Select text, an equation, or a diagram to copy.');return}
 if(document.execCommand('copy'))return;
 const item=selectedContentForClipboard();internalClipboard={html:item.html,plain:item.plain};
 notify('Copied to LaTeX Studio; use Paste to insert it.');
}
function makeBlocksDraggable(){editor.querySelectorAll('.math-block,.math-chip,.graph-block').forEach(el=>{el.draggable=true;el.setAttribute('title','Drag to move · Ctrl+C to copy · click to edit');el.tabIndex=0});}
function ancestorTopLevel(node){if(!node)return null;let el=node.nodeType===1?node:node.parentElement;while(el&&el.parentElement!==editor)el=el.parentElement;return el&&el.parentElement===editor?el:null}
function dropAnchorAt(e){let target=e.target.closest?.('.editor > *,.editor');if(!target||target===editor)return {anchor:null,after:true};target=ancestorTopLevel(target);if(!target)return {anchor:null,after:true};const r=target.getBoundingClientRect();return {anchor:target,after:e.clientY>r.top+r.height/2}}
function clearDragHints(){editor.querySelectorAll('.drag-before,.drag-after,.is-dragging').forEach(x=>x.classList.remove('drag-before','drag-after','is-dragging'))}
function wireEditorClipboardAndDrag(){
 editor.addEventListener('copy',e=>copyEventFromEditor(e));
 editor.addEventListener('cut',e=>copyEventFromEditor(e,true));
 editor.addEventListener('paste',pasteEventInEditor);
 editor.addEventListener('pointerdown',e=>{const el=e.target.closest('.math-chip,.math-block,.graph-block');if(el&&editor.contains(el))activePortableBlock=el;else activePortableBlock=null});
 editor.addEventListener('dragstart',e=>{
  const el=e.target.closest?.('.math-chip,.math-block,.graph-block');if(!el||!editor.contains(el))return;
  movingBlock=el;activePortableBlock=el;
  el.classList.add('is-dragging');
  const html=cleanPortableMarkup(el.outerHTML);e.dataTransfer.effectAllowed='copyMove';
  e.dataTransfer.setData('application/x-latex-studio-block',html);
  e.dataTransfer.setData('text/html',html);e.dataTransfer.setData('text/plain',el.dataset.latex||'LaTeX Studio diagram');
 });
 editor.addEventListener('dragover',e=>{
  if(!movingBlock)return;e.preventDefault();e.dataTransfer.dropEffect=e.ctrlKey?'copy':'move';
  clearDragHints();movingBlock.classList.add('is-dragging');
  lastDropAnchor=dropAnchorAt(e);const {anchor,after}=lastDropAnchor;if(anchor&&anchor!==movingBlock)anchor.classList.add(after?'drag-after':'drag-before');
 });
 editor.addEventListener('drop',e=>{
  const portable=e.dataTransfer?.getData('application/x-latex-studio-block');if(!movingBlock&&!portable)return;
  e.preventDefault();const item=movingBlock;
  let node=item;
  if(!node&&portable){const shell=document.createElement('div');shell.innerHTML=cleanPortableMarkup(portable);node=shell.firstElementChild}
  if(!node)return;
  if(e.ctrlKey&&item)node=item.cloneNode(true);
  const {anchor,after}=dropAnchorAt(e);
  if(anchor&&anchor!==item&&anchor!==node){anchor[after?'after':'before'](node)}
  else if(!anchor)editor.append(node);
  else if(e.ctrlKey&&anchor===item)anchor.after(node);
  activePortableBlock=node;clearDragHints();movingBlock=null;lastDropAnchor=null;
  renderAll();updateAll();notify(e.ctrlKey?'Copied block to new position.':'Moved block.');
 });
 editor.addEventListener('dragend',()=>{movingBlock=null;lastDropAnchor=null;clearDragHints()});
 editor.addEventListener('keydown',e=>{
  const node=e.target.closest?.('.math-block,.graph-block,.math-chip');if(!node||!e.altKey||!['ArrowUp','ArrowDown'].includes(e.key))return;
  e.preventDefault();const parent=ancestorTopLevel(node);if(!parent)return;
  if(e.key==='ArrowUp'&&parent.previousElementSibling)parent.previousElementSibling.before(parent);
  else if(e.key==='ArrowDown'&&parent.nextElementSibling)parent.nextElementSibling.after(parent);
  updateAll();node.focus();
 });
 // Every renderAll call uses the editor DOM, so also refresh after LaTeX typesetting.
 new MutationObserver(()=>{const list=editor.querySelectorAll('.math-chip:not([draggable]),.math-block:not([draggable]),.graph-block:not([draggable])');for(const n of list)n.draggable=true;}).observe(editor,{childList:true,subtree:true});
 makeBlocksDraggable();
}

